class Solution { public: string entityParser(string text){vector<pair<string,string>> entities={{"&quot;","\""},{"&apos;","'"},{"&amp;","&"},{"&gt;",">"},{"&lt;","<"},{"&frasl;","/"}};string answer;for(int i=0;i<(int)text.size();){bool matched=false;if(text[i]=='&')for(auto& [entity,value]:entities)if(text.compare(i,entity.size(),entity)==0){answer+=value;i+=entity.size();matched=true;break;}if(!matched)answer+=text[i++];}return answer;} };
